import json
from pathlib import Path
import numpy as np
from alphacrafter.sim.utils import register_hook, get_account_dict, get_stock_daily_data, rebalance_to_weights

UNIVERSE = ["000300.SH", "SPX", "HSI", "N225", "SX5E", "000688.SH", "SOX", "NDX", "XAU", "COPPER", "WTI", "BTC", "ETH", "US10Y", "CN10Y"]
FACTOR_WEIGHTS = {"clv": 0.3395, "peer": 0.2612, "reversal": 0.2012, "momentum": 0.1981}
MIN_W, MAX_W, REBALANCE_DAYS = 0.015, 0.16, 10
last_date = None


def ranks(values):
    result = {s: 0.5 for s in UNIVERSE}
    good = sorted((s, float(v)) for s, v in values.items() if np.isfinite(v))
    if len(good) < 2:
        return result
    for i, (s, _) in enumerate(good):
        result[s] = (i + 1.0) / len(good)
    return result


def bounded_weights(raw):
    # Simplex projection with the portfolio contract's sensible 15-name bounds.
    w = {s: max(0.0, float(raw.get(s, 0.0))) for s in UNIVERSE}
    z = sum(w.values()) or 1.0
    w = {s: x / z for s, x in w.items()}
    fixed = set()
    for _ in range(30):
        low = [s for s in UNIVERSE if s not in fixed and w[s] < MIN_W]
        high = [s for s in UNIVERSE if s not in fixed and w[s] > MAX_W]
        if not low and not high:
            break
        for s in low:
            w[s], fixed = MIN_W, fixed | {s}
        for s in high:
            w[s], fixed = MAX_W, fixed | {s}
        free = [s for s in UNIVERSE if s not in fixed]
        if not free:
            break
        rem = max(0.0, 1.0 - sum(w[s] for s in fixed))
        base = sum(max(w[s], 1e-12) for s in free)
        for s in free:
            w[s] = rem * w[s] / base
    z = sum(w.values()) or 1.0
    return {s: w[s] / z for s in UNIVERSE}


@register_hook
def cross_asset_strategy():
    global last_date
    account = get_account_dict()
    market = {}
    for s in UNIVERSE:
        df = get_stock_daily_data(symbol=s, days=85)
        if df is None or len(df) < 25:
            continue
        df = df.sort_values("date").reset_index(drop=True)
        c = np.asarray(df["close"], dtype=float)
        h = np.asarray(df["high"], dtype=float)
        l = np.asarray(df["low"], dtype=float)
        r = c[1:] / np.maximum(c[:-1], 1e-12) - 1.0
        market[s] = (c, h, l, r, str(df.iloc[-1]["date"]))
    if len(market) < 12:
        return
    decision = max(x[4] for x in market.values())
    if last_date is not None:
        try:
            elapsed = (np.datetime64(decision, "D") - np.datetime64(last_date, "D")) / np.timedelta64(1, "D")
            if elapsed < REBALANCE_DAYS:
                return
        except Exception:
            return

    clv, peer, reversal, momentum, invvol, five = {}, {}, {}, {}, {}, {}
    for s, (c, h, l, r, _) in market.items():
        daily_clv = (2*c - h - l) / np.maximum(h-l, 1e-12)
        vol = max(float(np.std(r[-20:])), 0.008)
        clv[s] = float(np.mean(daily_clv[-3:]))
        reversal[s] = float(-np.mean(r[-5:]))
        momentum[s] = float((c[-1] / max(c[-21], 1e-12) - 1.0) / (vol + 0.01))
        five[s] = float(c[-1] / max(c[-6], 1e-12) - 1.0)
        invvol[s] = 1.0 / vol
    med = float(np.median(list(five.values())))
    peer = {s: v - med for s, v in five.items()}
    ranked = {k: ranks(v) for k, v in (("clv", clv), ("peer", peer), ("reversal", reversal), ("momentum", momentum))}
    score = {s: sum(FACTOR_WEIGHTS[k] * ranked[k][s] for k in ranked) for s in UNIVERSE}

    # Sideways/mildly bullish assessment: retain diversification. In a confirmed
    # SPX downtrend, rotate some score toward defensive tradable benchmarks.
    if "SPX" in market:
        c = market["SPX"][0]
        if c[-1] < c[-21] and c[-1] < c[-6]:
            for s in ("XAU", "US10Y", "CN10Y"):
                score[s] += 0.18
            for s in ("BTC", "ETH", "WTI"):
                score[s] = max(0.05, score[s] - 0.10)
    mean_iv = float(np.mean(list(invvol.values()))) if invvol else 1.0
    raw = {s: max(0.01, score[s]) * (0.78 + 0.22 * invvol.get(s, mean_iv) / max(mean_iv, 1e-12)) for s in UNIVERSE}
    weights = bounded_weights(raw)
    score_mean = float(np.mean([score[s] for s in UNIVERSE]))
    score_std = float(np.std([score[s] for s in UNIVERSE]))
    forecast_returns = {s: 0.01 * (score[s] - score_mean) / max(score_std, 1e-12) for s in UNIVERSE}

    factor_ids = []
    try:
        p = Path(__file__).parent / "factors" / "factor_ensemble.json"
        ensemble = json.loads(p.read_text())
        factor_ids = [str(x["factor_id"]) for x in ensemble.get("selected_factors", [])
                      if isinstance(x, dict) and x.get("factor_id")][:10]
    except (OSError, ValueError, TypeError, KeyError):
        pass
    rebalance_to_weights(weights, forecast_returns=forecast_returns,
                         factor_ids=factor_ids, horizon_days=10)
    last_date = decision

