import json
from pathlib import Path
import numpy as np
from alphacrafter.sim.utils import register_hook, get_stock_daily_data, rebalance_to_weights

UNIVERSE = ["000300.SH", "SPX", "HSI", "N225", "SX5E", "000688.SH", "SOX", "NDX", "XAU", "COPPER", "WTI", "BTC", "ETH", "US10Y", "CN10Y"]
FACTOR_WEIGHTS = {"clv": 0.3395, "peer": 0.2612, "reversal": 0.2012, "momentum": 0.1981}
MIN_WEIGHT, MAX_WEIGHT, REBALANCE_DAYS = 0.015, 0.16, 10
last_decision = None
previous_score = None

def rank_cross_section(values):
    valid = sorted((s, float(v)) for s, v in values.items() if np.isfinite(v))
    result = {s: 0.5 for s in UNIVERSE}
    if len(valid) > 1:
        for i, (s, _) in enumerate(valid):
            result[s] = (i + 1.0) / len(valid)
    return result

def project_weights(raw):
    """Project positive scores to a fully invested vector with simple bounds."""
    free, fixed = set(UNIVERSE), {}
    raw = {s: max(float(raw.get(s, 0.0)), 1e-8) for s in UNIVERSE}
    for _ in range(20):
        if not free:
            break
        remainder = 1.0 - sum(fixed.values())
        scale = remainder / max(sum(raw[s] for s in free), 1e-12)
        low = [s for s in free if raw[s] * scale < MIN_WEIGHT]
        high = [s for s in free if raw[s] * scale > MAX_WEIGHT]
        if not low and not high:
            fixed.update({s: raw[s] * scale for s in free})
            break
        if low:
            for s in low:
                fixed[s] = MIN_WEIGHT
                free.remove(s)
        else:
            for s in high:
                fixed[s] = MAX_WEIGHT
                free.remove(s)
    if free:
        remainder = 1.0 - sum(fixed.values())
        total = sum(raw[s] for s in free)
        fixed.update({s: remainder * raw[s] / max(total, 1e-12) for s in free})
    total = sum(fixed.values())
    return {s: fixed.get(s, 0.0) / max(total, 1e-12) for s in UNIVERSE}

@register_hook
def cross_asset_strategy():
    global last_decision, previous_score
    series = {}
    for symbol in UNIVERSE:
        df = get_stock_daily_data(symbol=symbol, days=100)
        if df is None or len(df) < 35:
            continue
        df = df.sort_values("date").reset_index(drop=True)
        close = np.asarray(df["close"], dtype=float)
        high = np.asarray(df["high"], dtype=float)
        low = np.asarray(df["low"], dtype=float)
        ret = close[1:] / np.maximum(close[:-1], 1e-12) - 1.0
        series[symbol] = (close, high, low, ret, str(df.iloc[-1]["date"]))
    if len(series) < 12:
        return
    decision_date = max(x[4] for x in series.values())
    if last_decision is not None:
        try:
            if (np.datetime64(decision_date) - np.datetime64(last_decision)) / np.timedelta64(1, "D") < REBALANCE_DAYS:
                return
        except Exception:
            return

    clv, peer, reversal, momentum, invvol = {}, {}, {}, {}, {}
    for s, (c, h, l, r, _) in series.items():
        candle = (2.0 * c - h - l) / np.maximum(h - l, 1e-12)
        volatility = max(float(np.std(r[-20:])), 0.008)
        clv[s] = float(np.mean(candle[-5:]))       # smoothed one-day pressure
        reversal[s] = float(-np.mean(r[-5:]))
        momentum[s] = float((c[-1] / max(c[-21], 1e-12) - 1.0) / (volatility + 0.01))
        peer[s] = float(c[-1] / max(c[-6], 1e-12) - 1.0)
        invvol[s] = 1.0 / volatility
    median_peer = float(np.median(list(peer.values())))
    peer = {s: v - median_peer for s, v in peer.items()}
    ranked = {k: rank_cross_section(v) for k, v in
              (("clv", clv), ("peer", peer), ("reversal", reversal), ("momentum", momentum))}
    score = {s: sum(FACTOR_WEIGHTS[k] * ranked[k][s] for k in FACTOR_WEIGHTS) for s in UNIVERSE}
    # Damp short-horizon score changes to control turnover, without using future data.
    if previous_score is not None:
        score = {s: 0.60 * previous_score.get(s, score[s]) + 0.40 * score[s] for s in UNIVERSE}
    previous_score = dict(score)

    breadth = float(np.mean([series[s][0][-1] > series[s][0][-21] for s in series]))
    bearish = False
    if "SPX" in series:
        spx = series["SPX"][0]
        bearish = (spx[-1] < spx[-31] and spx[-1] < spx[-11] and breadth < 0.50)
    # In a bullish/moderate regime retain trend exposure. In a confirmed bear regime,
    # rotate toward tradable defensive benchmarks while remaining fully invested.
    if bearish:
        for s in ("XAU", "US10Y", "CN10Y"):
            score[s] += 0.12
        for s in ("BTC", "ETH", "WTI"):
            score[s] = max(0.05, score[s] - 0.06)

    mean_iv = float(np.mean(list(invvol.values())))
    raw = {s: max(score[s], 0.02) * (0.70 + 0.30 * invvol[s] / max(mean_iv, 1e-12)) for s in UNIVERSE}
    weights = project_weights(raw)
    avg, sd = float(np.mean(list(score.values()))), max(float(np.std(list(score.values()))), 1e-12)
    forecast = {s: 0.01 * (score[s] - avg) / sd for s in UNIVERSE}
    try:
        ensemble = json.loads((Path(__file__).parent / "factors" / "factor_ensemble.json").read_text())
        factor_ids = [x["factor_id"] for x in ensemble.get("selected_factors", [])
                      if isinstance(x, dict) and x.get("factor_id")][:10]
    except Exception:
        factor_ids = []
    # Complete 15-asset target; helper handles fractional quantities and 3bp gate.
    rebalance_to_weights(weights, forecast_returns=forecast, factor_ids=factor_ids, horizon_days=10)
    last_decision = decision_date

if __name__ == "__main__":
    pass

